 private static final EntityDataAccessor<Integer> ROLE=SynchedEntityData.defineId(DogheadEntity.class,EntityDataSerializers.INT),CLIP=SynchedEntityData.defineId(DogheadEntity.class,EntityDataSerializers.INT),NONCE=SynchedEntityData.defineId(DogheadEntity.class,EntityDataSerializers.INT);
