 public UUID pack=UUID.randomUUID();public boolean spawnRejected;private boolean founder;private int naturalCheck,ambientIn=300,preyCheck=200,blockedTicks;private long attackAfter,sweepAfter,howlAfter,switchAfter,dodgeAfter,preyAfter,interestUntil,seenAt,replyAt,retreatUntil,approachUntil;private UUID tracked;private Vec3 lastSeen,slot,formationTarget;private float attackYaw,stepPhase;private Vec3 stepPosition;
